TextTheme _falconTextTheme(ColorScheme c) => TextTheme(
  headlineMedium: TextStyle(fontFamily: FalconTokens.fontDisplay, fontSize: 40, height: 1.1000, fontWeight: FontWeight.w600),
  headlineSmall: TextStyle(fontFamily: FalconTokens.fontDisplay, fontSize: 24, height: 1.2500, fontWeight: FontWeight.w600),
  titleMedium: TextStyle(fontFamily: FalconTokens.fontSans, fontSize: 18, height: 1.4444, fontWeight: FontWeight.w600),
  bodyLarge: TextStyle(fontFamily: FalconTokens.fontSans, fontSize: 16, height: 1.5000, fontWeight: FontWeight.w400),
  bodyMedium: TextStyle(fontFamily: FalconTokens.fontSans, fontSize: 15, height: 1.4667, fontWeight: FontWeight.w400),
