  labelLarge: TextStyle(fontFamily: FalconTokens.fontSans, fontSize: 14, height: 1.4286, fontWeight: FontWeight.w500),
).apply(bodyColor: c.onSurface, displayColor: c.onSurface);

ThemeData falconTheme(Brightness brightness) {
  final dark = brightness == Brightness.dark;
  final scheme = dark ? falconDarkScheme : falconLightScheme;
  final colors = dark ? FalconColors.dark : FalconColors.light;
  final controlShape = RoundedRectangleBorder(borderRadius: BorderRadius.circular(FalconTokens.radiusMd));
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    scaffoldBackgroundColor: scheme.surface,
    fontFamily: FalconTokens.fontSans,
    textTheme: _falconTextTheme(scheme),
    extensions: [colors],
    cardTheme: CardThemeData(
      color: scheme.surfaceContainerLow,
      elevation: 0,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(FalconTokens.radiusCard),
        side: BorderSide(color: scheme.outlineVariant),
      ),
    ),
    filledButtonTheme: FilledButtonThemeData(
      style: FilledButton.styleFrom(
        backgroundColor: scheme.primaryContainer,
        foregroundColor: scheme.onPrimaryContainer,
        minimumSize: const Size(0, FalconTokens.sizeControlLg),
        shape: controlShape,
      ),
    ),
    inputDecorationTheme: InputDecorationTheme(
      border: OutlineInputBorder(borderRadius: BorderRadius.circular(FalconTokens.radiusMd), borderSide: BorderSide(color: scheme.outline)),
      focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(FalconTokens.radiusMd), borderSide: BorderSide(color: colors.focus, width: FalconTokens.sizeFocusWidth)),
    ),
  );
}
